"""Chapter 4 examples, version 3.4.0 - the twenty-one code examples of the chapter 4 deck 3.4.0 (new file; examples_v1_0_0, v2_0_0 and v2_1_0 are the earlier decks' and stay as they are).
Each example is a listing of single-line statements, the last one an expression whose repr the deck prints under the listing; `show` lists the expressions whose values the
result picture of the slide is drawn from (the first is the printed one). The listings run after the PRELUDE, one fresh namespace each, and call the chapter library
sen0401_ch04_lib_v1_0_0 as K. Nothing here records an answer: examples_run_v3_4_0.py runs every listing and writes examples_out_v3_4_0.json; the deck is drawn from that file.
No listing prints an error first: where the chapter teaches a rejection the listing prints plain values (True, False, counts), never a traceback."""
__version__ = "3.4.0"
PRELUDE = "import hashlib\nimport math\nimport sen0401_ch04_lib_v1_0_0 as K\n"
LIB = "sen0401_ch04_lib_v1_0_0"

P1, P2, P3, P4, P5 = ("Public Key Cryptography", "Legacy Addresses", "Script Hashes and Bech32", "Private Key Formats", "Advanced Keys and Addresses")

G = lambda lines, note: {"lines": lines, "note": note}
EXAMPLES = [
 {"id": "ex01", "name": "A private key is a number below n", "branch": P1, "picture": "table",
  "groups": [G(["k = K.BOOK_K"], "The private key of the book's example: one very large whole number."),
             G(["ok = lambda x: 0 < x < K.N", "[ok(x) for x in (0, 1, k, K.N - 1, K.N)]"], "A key is valid when it lies strictly between 0 and n; the list gives five verdicts.")],
  "show": ["[ok(x) for x in (0, 1, k, K.N - 1, K.N)]", "[x.bit_length() for x in (0, 1, k, K.N - 1, K.N)]"]},
 {"id": "ex02", "name": "Entropy: bits an attacker must guess", "branch": P1, "picture": "native chart",
  "groups": [G(["b = K.bits_of"], "Entropy is the length times the base-2 logarithm of the size of the alphabet."),
             G(["[b(10, 4), b(26, 8), b(94, 12), b(2, 256)]"], "A PIN, a lowercase word, a long password and 256 fair coin flips.")],
  "show": ["[b(10, 4), b(26, 8), b(94, 12), b(2, 256)]", "round(math.log2(K.N))"]},
 {"id": "ex03", "name": "The curve secp256k1 and its generator", "branch": P1, "picture": "table",
  "groups": [G(["x, y = K.G"], "The generator point G: the fixed starting point that every key multiplies."),
             G(["left, right = y * y % K.P, (x ** 3 + 7) % K.P", "left == right"], "Both sides of y squared equals x cubed plus 7 agree, counted modulo the prime p.")],
  "show": ["left == right", "K.P.bit_length()", "hex(x)[:12]", "K.P == 2 ** 256 - 2 ** 32 - 977"]},
 {"id": "ex04", "name": "Doubling and adding: k times G", "branch": P1, "picture": "table",
  "groups": [G(["pts = [K.ec_mul(n) for n in (1, 2, 3, 4)]"], "Multiply G by one, two, three and four; every result is another point."),
             G(["twice = K.ec_add(K.G, K.G)", "twice == pts[1]"], "Adding G to itself gives 2G, the same point that the multiplication found.")],
  "show": ["twice == pts[1]", "[hex(p[0])[2:10] for p in pts]", "(K.BOOK_K.bit_length() - 1, bin(K.BOOK_K).count('1') - 1)"]},
 {"id": "ex05", "name": "The point at infinity on a toy curve", "branch": P1, "picture": "table",
  "groups": [G(["pts = K.multiples(10)"], "Walk the multiples of one point on a toy curve over only 17 numbers."),
             G(["pts.index(None) + 1"], "The ninth multiple is None, the point at infinity: the walk closes into a cycle.")],
  "show": ["pts.index(None) + 1", "pts[:9]", "K.small_add(pts[7], K.SMALL_PT, 17) is None"]},
 {"id": "ex06", "name": "One-way: the work to find a key", "branch": P1, "picture": "native chart",
  "groups": [G(["b = [20, 40, 80, 128, 256]"], "Key sizes in bits, from a toy key to the size Bitcoin uses."),
             G(["[round(math.log10(2 ** (n - 1))) for n in b]"], "Half the keys must be tried on average; the list gives that as a power of ten.")],
  "show": ["[round(math.log10(2 ** (n - 1))) for n in b]", "2 ** 19"]},
 {"id": "ex07", "name": "A public key has two encodings", "branch": P2, "picture": "table",
  "groups": [G(["Kp = K.ec_mul(K.BOOK_K)"], "Multiply G by the book's private key: the public key is a point (x, y)."),
             G(["c, u = K.pub_bytes(Kp), K.pub_bytes(Kp, False)", "(len(c), len(u), c[0], u[0])"], "Compressed keeps x and a parity byte; uncompressed writes x and y after 04.")],
  "show": ["(len(c), len(u), c[0], u[0])", "K.decompress(c) == Kp", "round(1 - 33 / 65, 3)"]},
 {"id": "ex08", "name": "P2PK holds the key, P2PKH only its hash", "branch": P2, "picture": "table",
  "groups": [G(["c = K.pub_bytes(K.ec_mul(K.BOOK_K))"], "The compressed public key of the book's example."),
             G(["pk, pkh = K.p2pk_script(c), K.p2pkh_script(c)", "(len(pk), len(pkh))"], "P2PK holds the key itself; P2PKH holds only a 20-byte hash of it, a commitment.")],
  "show": ["(len(pk), len(pkh))", "pkh[3:23] == K.hash160(c)", "(pk[-1], pkh[-1])"]},
 {"id": "ex09", "name": "HASH160 is SHA256 then RIPEMD-160", "branch": P2, "picture": "native chart",
  "groups": [G(["c = K.pub_bytes(K.ec_mul(K.BOOK_K))", "s = hashlib.sha256(c).digest()"], "SHA256 turns the 33-byte key into a 32-byte fingerprint."),
             G(["r = K.ripemd160(s)", "(len(c), len(s), len(r), r == K.hash160(c))"], "RIPEMD-160 shortens it to 20 bytes; the pair of hashes is what HASH160 means.")],
  "show": ["(len(c), len(s), len(r), r == K.hash160(c))", "r.hex()"]},
 {"id": "ex10", "name": "Base58Check, step by step", "branch": P2, "picture": "table",
  "groups": [G(["h = K.hash160(K.pub_bytes(K.ec_mul(K.BOOK_K)))"], "The 20-byte key hash of the book's example."),
             G(["body = b'\\x00' + h", "chk = K.dsha(body)[:4]"], "Put the version byte 00 in front; the checksum is four bytes of a double SHA256."),
             G(["addr = K.b58check(body)", "(len(body + chk), len(addr), addr[0])"], "Twenty-five bytes in base58 become a 34-character address that starts with 1.")],
  "show": ["(len(body + chk), len(addr), addr[0])", "chk.hex()", "addr", "addr == K.key_to_address(K.BOOK_K)", "h.hex()[:8]"]},
 {"id": "ex11", "name": "The checksum catches every single typo", "branch": P2, "picture": "table",
  "groups": [G(["good = K.key_to_address(K.BOOK_K)"], "The example address; now change one character at a time."),
             G(["typos = K.single_typos(good)", "(len(typos), sum(map(K.is_valid_b58check, typos)))"], "Try every one-character substitution; the pair counts the typos and the accepted ones.")],
  "show": ["(len(typos), sum(map(K.is_valid_b58check, typos)))", "K.is_valid_b58check(good)", "2 ** 32"]},
 {"id": "ex12", "name": "P2SH commits to a whole script", "branch": P3, "picture": "table",
  "groups": [G(["keys = [K.pub_bytes(K.ec_mul(n)) for n in (1, 2, 3)]"], "Three public keys for a two-of-three multisignature wallet."),
             G(["script = K.multisig_script(2, keys)"], "The redeem script lists the keys and asks for any two signatures."),
             G(["addr = K.p2sh(script)", "(len(script), addr[0], len(addr))"], "The address is HASH160 of that script with version 05, so it starts with 3.")],
  "show": ["(len(script), addr[0], len(addr))", "K.hash160(script).hex()[:12]", "addr"]},
 {"id": "ex13", "name": "Collision and preimage: bits of work", "branch": P3, "picture": "native chart",
  "groups": [G(["col, pre = (lambda n: n // 2), (lambda n: n)"], "A hash of n bits falls to a collision after about 2 to the n over 2 tries."),
             G(["[col(160), pre(160), col(256), pre(256)]"], "A preimage needs 2 to the n tries; the list gives the exponents for two hash sizes.")],
  "show": ["[col(160), pre(160), col(256), pre(256)]"]},
 {"id": "ex14", "name": "A Bech32 address, taken apart", "branch": P3, "picture": "table",
  "groups": [G(["addr = K.segwit_address('bc', 0, K.PROG_WPKH)"], "A version 0 SegWit address for the book's key hash."),
             G(["hrp, _, rest = addr.rpartition('1')", "[hrp, rest[0], len(rest[1:-6]), rest[-6:]]"], "Split at the last 1: network name, version letter, program letters, checksum.")],
  "show": ["[hrp, rest[0], len(rest[1:-6]), rest[-6:]]", "addr", "len(addr)"]},
 {"id": "ex15", "name": "Witness version and witness program", "branch": P3, "picture": "table",
  "groups": [G(["p = [(0, K.PROG_WPKH), (0, K.PROG_WSH), (1, K.PROG_TR)]", "a = [K.segwit_address('bc', v, g) for v, g in p]"], "Three programs from the book: a key hash, a script hash and a Taproot key."),
             G(["d = [K.segwit_decode('bc', x) for x in a]", "[(v, len(g)) for v, g in d]"], "Decoding each address returns the witness version and the program length.")],
  "show": ["[(v, len(g)) for v, g in d]", "[x[:4] for x in a]", "[len(x) for x in a]"]},
 {"id": "ex16", "name": "Bech32 accepts the extra q, Bech32m does not", "branch": P3, "picture": "table",
  "groups": [G(["ok = lambda a, c: K.bech_check(a) == c"], "A string passes when its checksum equals the constant of the format."),
             G(["old = [ok(a, K.BECH32) for a in K.EXT]", "new = [ok(a, K.BECH32M) for a in K.EXT]", "(old, new)"], "The book's strings insert q before the last p; the old checksum cannot tell.")],
  "show": ["(old, new)", "[len(a) for a in K.EXT]"]},
 {"id": "ex17", "name": "WIF: a private key dressed for travel", "branch": P4, "picture": "table",
  "groups": [G(["k = K.BOOK_K", "w, wc = K.wif(k, False), K.wif(k)"], "The same key written twice: as WIF and as WIF-compressed."),
             G(["(w[0], len(w), wc[0], len(wc))"], "The first form starts with 5 and has 51 characters; the second starts with K or L and has 52.")],
  "show": ["(w[0], len(w), wc[0], len(wc))", "(len(K.b58check_decode(w)), len(K.b58check_decode(wc)))", "K.b58check_decode(wc)[-1]"]},
 {"id": "ex18", "name": "One private key, two addresses", "branch": P4, "picture": "table",
  "groups": [G(["k = K.BOOK_K", "a1 = K.key_to_address(k, False)", "a2 = K.key_to_address(k, True)"], "Hash the 65-byte key and then the 33-byte key: two different addresses."),
             G(["(a1[:6], a2[:6], a1 != a2)"], "The compressed flag in WIF tells a wallet which of the two addresses it must watch.")],
  "show": ["(a1[:6], a2[:6], a1 != a2)", "(a1, a2)"]},
 {"id": "ex19", "name": "Vanity search: 58 times harder per letter", "branch": P5, "picture": "native chart",
  "groups": [G(["a = K.key_to_address", "n = next(i for i in range(1, 900) if a(i)[1] == 'A')"], "Try keys 1, 2, 3 until the address has A as its first letter after the 1."),
             G(["[n, a(n)[:3]]"], "One chosen letter took this many tries; each further letter costs 58 times more.")],
  "show": ["[n, a(n)[:3]]", "[58 ** m for m in range(1, 7)]"]},
 {"id": "ex20", "name": "A paper wallet must give back its address", "branch": P5, "picture": "table",
  "groups": [G(["w, a = K.wif(K.BOOK_K), K.key_to_address(K.BOOK_K)"], "A paper wallet prints two strings: the secret WIF key and the public address."),
             G(["raw = K.b58check_decode(w)", "back = int.from_bytes(raw[1:33], 'big')"], "Scanning the paper decodes the key from its WIF text."),
             G(["K.key_to_address(back) == a"], "The restored key must reproduce the printed address; test it before you fund it.")],
  "show": ["K.key_to_address(back) == a", "(len(w), len(a))", "(raw[0], raw[-1])"]},
 {"id": "ex21", "name": "The eater address is valid but keyless", "branch": P5, "picture": "table",
  "groups": [G(["e = K.EATER", "msg, tail = e[1:28], e[28:]"], "The address spells a message after the leading 1; six more letters close it."),
             G(["(msg, tail, K.is_valid_b58check(e))"], "The checksum is correct, so a wallet accepts the address without any warning.")],
  "show": ["(msg, tail, K.is_valid_b58check(e))", "len(K.b58check_decode(e))", "K.b58check_decode(e)[1:].hex()"]},
]
for _e in EXAMPLES:
    _e["lines"] = [l for g in _e["groups"] for l in g["lines"]]
